import { describe, expect, it } from 'vitest'

import { studioSubmissionError } from '../studio-errors'

describe('Studio safe error messages', () => {
  it('explains source incompatibility without exposing the provider response', () => {
    expect(
      studioSubmissionError({
        isAxiosError: true,
        response: {
          status: 409,
          data: {
            message:
              '{"detail":"The source task was generated by an upstream provider that does not support this operation"}',
          },
        },
      })
    ).toBe(
      'This song source does not support this operation. Choose another song or use the MP3 result.'
    )
  })
  it('explains a model with no available provider without revealing routing tiers', () => {
    expect(
      studioSubmissionError({
        isAxiosError: true,
        response: {
          status: 404,
          data: {
            error: {
              message:
                "No provider configured for this model on channels ['regular', 'official']",
            },
          },
        },
      })
    ).toBe(
      'This model is temporarily unavailable. Please choose another model.'
    )
  })
  it('never echoes unknown upstream messages or secrets', () => {
    expect(
      studioSubmissionError({
        isAxiosError: true,
        response: { status: 500, data: { message: 'private-provider-key' } },
      })
    ).not.toContain('private-provider-key')
  })
})
